INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52811, 'Psalms 49:18', 'Psalms', 49, 18, 'که څه هم هغه په ژوند کې بختور ګڼي خپل ځان صفت یې کیږي ځکه هر کار کې کامیاب وي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_18.mp3', '', 1761754199, 1761754199),
(52812, 'Psalms 49:19', 'Psalms', 49, 19, 'دی به په مرګ کې شي یوځای خپلو نیکونو سره هغوی به هېڅکله رڼا نه ویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_19.mp3', '', 1761754199, 1761754199),
(52813, 'Psalms 49:20', 'Psalms', 49, 20, 'انسان لري شان او شوکت خو هغه نه پوهیږي چې شي به مړ لکه څارویو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_20.mp3', '', 1761754199, 1761754199),
(52814, 'Judges 15:1', 'Judges', 15, 1, 'څه موده وروسته د غنمو د لو په وخت کې شمشون د خپلې ښځې د لیدلو دپاره ورغی او هغې ته یې د سوغات په توګه یو سېرلی یووړ. شمشون د هغې پلار ته وویل: «زه غواړم چې د خپلې ښځې کوټې ته لاړ شم.» خو هغه ورته اجازه ورنه کړه چې دننه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_1.mp3', '', 1761754199, 1761754199),
(52815, 'Judges 15:2', 'Judges', 15, 2, 'هغه شمشون ته وویل: «ما په رښتیا فکر کاوه چې ته د هغې څخه کرکه کوې، نو هغه ما ستا ملګري ته ورکړه. خو د هغې کشره خور د هغې څخه ډېره ښایسته ده، د دې په ځای ته کولای شې د هغې سره واده وکړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_2.mp3', '', 1761754199, 1761754199),
(52816, 'Judges 15:3', 'Judges', 15, 3, 'شمشون وویل: «دا ځل چې په فلسطینیانو باندې هرڅه وکړم زه به بې ګناه یم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_3.mp3', '', 1761754199, 1761754199),
(52817, 'Judges 15:4', 'Judges', 15, 4, 'نو هغه لاړ او درې سوه ګیدړان یې ونیول او یوه یوه جوړه یې لکۍ په لکۍ سره وتړل. بیا هغه د لکیو په هرې جوړې پورې یو یو څراغ وتاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_4.mp3', '', 1761754199, 1761754199),
(52818, 'Judges 15:5', 'Judges', 15, 5, 'بیا یې څراغونو ته اور واچاوه او ګیدړان یې د فلسطینیانو په ولاړو فصلونو کې خوشې کړل. هغه د ګېډیو انبارونه او ولاړ فصلونه د انګورو او زیتونو د باغونو سره وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_5.mp3', '', 1761754199, 1761754199),
(52819, 'Judges 15:6', 'Judges', 15, 6, 'کله چې فلسطینیانو پوښتنه وکړه چې «دا کار چا کړی دی؟» کوم چا هغوی خبر کړل چې «دا کار شمشون کړی دی، ځکه چې د هغه خسر چې د تمنې څخه دی، د شمشون ښځه د هغه ملګري ته واده کړې وه.» نو فلسطینیان لاړل او هغه ښځه او د هغې پلار یې ژوندي وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_6.mp3', '', 1761754199, 1761754199),
(52820, 'Judges 15:7', 'Judges', 15, 7, 'شمشون هغوی ته وویل: «څرنګه چې تاسو داسې کار کړی دی، نو زه قسم خورم چې ترڅو پورې مې ستاسو څخه د هغوی بدل نه وي اخیستی تر هغې پورې به ارام نه کښېنم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_7.mp3', '', 1761754199, 1761754199),
(52821, 'Judges 15:8', 'Judges', 15, 8, 'شمشون په هغوی باندې ډېره سخته حمله وکړه او ډېر کسان یې ورڅخه ووژل. بیا هغه لاړ او د عیطام د ګټ په سمڅه کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_8.mp3', '', 1761754199, 1761754199),
(52822, 'Judges 15:9', 'Judges', 15, 9, 'فلسطینیان لاړل او د یهودا په سیمه کې یې خېمې ودرولې او د لحي په ښارګوټي باندې یې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_9.mp3', '', 1761754199, 1761754199),
(52823, 'Judges 15:10', 'Judges', 15, 10, 'د یهودا خلکو پوښتنه وکړه: «تاسو ولې په مونږ باندې حمله کوئ؟» هغوی په ځواب کې وویل: «مونږ د دې دپاره راغلي یو چې شمشون ونیسو او هغه کار ورسره وکړو چې هغه زمونږ سره وکړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_10.mp3', '', 1761754199, 1761754199),
(52824, 'Judges 15:11', 'Judges', 15, 11, 'نو د یهودا درې زره کسان د عیطام د ګټ سمڅې ته لاړل او شمشون ته یې وویل: «ته خبر نه یې چې فلسطینیان په مونږ باندې حکومت کوي؟ تا زمونږ سره څه وکړل؟» هغه په ځواب کې وویل: «کوم کار چې هغوی زما سره کړی ؤ، ما هم د هغوی سره هماغسې کار وکړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_11.mp3', '', 1761754199, 1761754199),
(52825, 'Judges 15:12', 'Judges', 15, 12, 'هغوی ورته وویل: «مونږ د دې دپاره راغلي یو چې تا وتړو او فلسطینیانو ته دې وسپارو.» شمشون وویل: «ماته قسم وخورئ چې تاسو به مې په خپله نه وژنئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_12.mp3', '', 1761754199, 1761754199),
(52826, 'Judges 15:13', 'Judges', 15, 13, 'هغوی وویل: «سمه ده، مونږ به ستا لاسونه وتړو او هغوی ته به دې وسپارو. مونږ به تا نه وژنو.» نو هغوی په دوو نویو رسۍ ګانو باندې د هغه لاسونه وتړل او د ګټ څخه یې بېرته راوست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_13.mp3', '', 1761754199, 1761754199),
(52827, 'Judges 15:14', 'Judges', 15, 14, 'کله چې شمشون لحي ته ورسېده، فلسطینیان په منډه د هغه خواته ورغلل او چیغې یې وهلې. ناڅاپه د څښتن روح هغه قوي کړ او هغه رسۍ ګانې یې چې د هغه لاسونه ورباندې تړل شوي وو لکه د سوځېدلي کتان په شان وشکولې او هغه ولوېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_14.mp3', '', 1761754199, 1761754199),
(52828, 'Judges 15:15', 'Judges', 15, 15, 'بیا شمشون د یوه داسې خره د ژامې هډوکی پیدا کړ چې په هماغو نژدې وختونو کې مردار شوی ؤ. هغه خپل لاس وراوږد کړ، هغه یې راواخیست او زر تنه یې ورباندې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_15.mp3', '', 1761754199, 1761754199),
(52829, 'Judges 15:16', 'Judges', 15, 16, 'نو شمشون وویل: ما زر کسان ووژل د خره د ژامې په هډوکي باندې ما د مړو څخه جوړې ډېرۍ ګانې کړلې د خره د ژامې په هډوکي باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_16.mp3', '', 1761754199, 1761754199),
(52830, 'Judges 15:17', 'Judges', 15, 17, 'کله چې هغه خپلې خبرې خلاصې کړې، نو د ژامې هډوکی یې په ځمکه وغورځاوه او هغه ځای یې د ژامې د هډوکي د غونډۍ په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_17.mp3', '', 1761754199, 1761754199),
(52831, 'Judges 15:18', 'Judges', 15, 18, 'بیا شمشون ډېر تږی شو، نو هغه څښتن ته فریاد وکړ او ویې ویل: «تا خپل بنده ته داسې لوی بری ورکړ. ایا اوس به د تندې څخه مړ کېږم او دې کافرو فلسطینیانو ته به په لاس ورځم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_18.mp3', '', 1761754199, 1761754199),
(52832, 'Judges 15:19', 'Judges', 15, 19, 'بیا خدای هلته په لحي کې په ځمکه کې د یو تش ځای څخه اوبه جاري کړلې. شمشون هغه وڅښلې او بیا یې قوت وموند او تازه شو. نو هغه چینه یې د فریاد کوونکي د چینې په نوم یاده کړه او هغه تر اوسه پورې په لحي کې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_19.mp3', '', 1761754199, 1761754199),
(52833, 'Judges 15:20', 'Judges', 15, 20, 'شمشون د فلسطینیانو د واکمنۍ په دوران کې شل کاله د اسراییلو قاضي ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges15_verse_20.mp3', '', 1761754199, 1761754199),
(52834, 'Nehemiah 3:1', 'Nehemiah', 3, 1, 'بیا لوی کاهن الیاشیب او د هغه ملګرو کاهنانو د پسونو دروازه بېرته جوړه کړه، هغه یې وقف کړه او دروازې یې بېرته په خپل ځای کې کېښودلې. هغوی هغه دېوال د سلو د برج او د حنن ییل تر برج پورې ودان او وقف کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_1.mp3', '', 1761754199, 1761754199),
(52835, 'Nehemiah 3:2', 'Nehemiah', 3, 2, 'د دېوال بله برخه د اریحا خلکو ودانه کړه. ورپسې برخه یې د امري زوی زکور ودانه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_2.mp3', '', 1761754199, 1761754199),
(52836, 'Nehemiah 3:3', 'Nehemiah', 3, 3, 'د هسناه طایفې د ماهيانو دروازه جوړه کړه. هغوی تیرونه او دروازې په خپلو ځایونو کې کېښودلې او په هغو کې یې د دروازې د بندولو دپاره قلفکونه او اړمونه هم کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_3.mp3', '', 1761754199, 1761754199),
(52837, 'Nehemiah 3:4', 'Nehemiah', 3, 4, 'مریموت چې د اوریا زوی او د هقوس لمسی ؤ، د دېوال بله برخه جوړه کړه. د برکیا زوی او د مشیزبییل لمسي مشلام د دېوال بله برخه جوړه کړه او بله برخه یې صادوق د بعنه زوی جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_4.mp3', '', 1761754199, 1761754199),
(52838, 'Nehemiah 3:5', 'Nehemiah', 3, 5, 'د دېوال بله برخه د تقوع خلکو جوړه کړه، خو د تقوع مشرانو د هغه کار څخه انکار وکړ چې د کار د مسوولانو له خوا هغوی ته ورسپارل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_5.mp3', '', 1761754199, 1761754199),
(52839, 'Nehemiah 3:6', 'Nehemiah', 3, 6, 'یویاداع د فاسیح زوی او مشلام د بسودیا زوی د یشانه دروازه جوړه کړه. هغوی تیرونه او د دروازې پلې په خپلو ځایونو کې کېښودلې او په هغو کې یې د دروازې د بندولو دپاره قلفکونه او اړمونه هم کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_6.mp3', '', 1761754199, 1761754199),
(52840, 'Nehemiah 3:7', 'Nehemiah', 3, 7, 'د جبعون څخه ملتیا، د میرونوت څخه یادون او د جبعون او مصفه خلکو د فرات د سیند د لوېدیځې خوا د سیمې د والي تر استوګنځي پورې د دېوال بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_7.mp3', '', 1761754199, 1761754199),
(52841, 'Nehemiah 3:8', 'Nehemiah', 3, 8, 'د دېوال بله برخه عزییل د حرهایا زوی چې زرګر ؤ، جوړه کړه. حننیا چې د عطر جوړوونکو څخه ؤ، تر پلن دېواله پورې د دېوال بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_8.mp3', '', 1761754199, 1761754199),
(52842, 'Nehemiah 3:9', 'Nehemiah', 3, 9, 'رفایا د حور زوی چې د اورشلیم د نیمې ناحیې حاکم ؤ، د دېوال بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_9.mp3', '', 1761754199, 1761754199),
(52843, 'Nehemiah 3:10', 'Nehemiah', 3, 10, 'یدعیا د حروماف زوی د دېوال هغه برخه جوړه کړه چې د هغه د کور مخې ته وه. د دېوال بله برخه حطوش د حشبنیا زوی جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_10.mp3', '', 1761754199, 1761754199),
(52844, 'Nehemiah 3:11', 'Nehemiah', 3, 11, 'ملکیا د حاریم زوی او حشوب د فحت موآب زوی د دېوال ورپسې برخه او هم د تنورونو برج جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_11.mp3', '', 1761754199, 1761754199),
(52845, 'Nehemiah 3:12', 'Nehemiah', 3, 12, 'شلوم د هلوحیش زوی چې د اورشلیم د بلې نیمې ناحیې حاکم ؤ، د دېوال بله برخه جوړه کړه. د هغه لورګانو د هغه سره په دې کار کې مرسته وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_12.mp3', '', 1761754199, 1761754199),
(52846, 'Nehemiah 3:13', 'Nehemiah', 3, 13, 'حانون او د زانوح د ښار اوسېدونکو د درې دروازه بېرته جوړه کړه. هغوی د دروازې پلې په خپلو ځایونو کې کېښودلې او په هغو کې یې د دروازې د بندولو دپاره قلفکونه او اړمونه هم کېښودل. وروسته یې د خزلو د دروازې پورې څلور سوه او پنځوس متره دېوال بیا جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_13.mp3', '', 1761754199, 1761754199),
(52847, 'Nehemiah 3:14', 'Nehemiah', 3, 14, 'ملکیا د رکاب زوی چې د بیت هکاریم د ناحیې حاکم ؤ، د خزلو دروازه بېرته جوړه کړه. هغه د دروازې پلې په خپلو ځایونو کې کېښودلې او په هغو کې یې د دروازې د بندولو دپاره قلفکونه او اړمونه هم کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_14.mp3', '', 1761754199, 1761754199),
(52848, 'Nehemiah 3:15', 'Nehemiah', 3, 15, 'شلون د کلحوزه زوی چې د مصفه د ناحیې حاکم ؤ، د فوارې دروازه بېرته جوړه کړه. هغه د دروازې چت جوړ کړ، د دروازې پلې یې په خپلو ځایونو کې کېښودلې او په هغو کې یې د دروازې د بندولو دپاره قلفکونه او اړمونه هم کېښودل. هغه د سیلوحا د حوض څخه چې د شاهي باغ په څنګ کې ؤ د هغو زینو پورې چې د داود د ښار څخه کوزې شوې وې، دېوال ودان کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_15.mp3', '', 1761754199, 1761754199),
(52849, 'Nehemiah 3:16', 'Nehemiah', 3, 16, 'نحمیا د عزبوق زوی چې د بیت صور د نیمې ناحیې حاکم ؤ، د دېوال بله برخه چې د داود د کورنۍ هدیرې، حوض او عسکري قشلو پورې رسېدله، جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_16.mp3', '', 1761754199, 1761754199),
(52850, 'Nehemiah 3:17', 'Nehemiah', 3, 17, 'هغه لاویان چې د دېوال څو نورې برخې یې جوړې کړې، دا دي: رحوم د باني زوی لومړنۍ برخه جوړه کړه. حشبیا چې د قعیلې د نیمې ناحیې حاکم ؤ، د خپلې ناحیې په استازیتوب بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_17.mp3', '', 1761754199, 1761754199),
(52851, 'Nehemiah 3:18', 'Nehemiah', 3, 18, 'بوای د حیناداد زوی چې د قعلې د ناحیې د بلې نیمایي برخې حاکم ؤ، بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_18.mp3', '', 1761754199, 1761754199),
(52852, 'Nehemiah 3:19', 'Nehemiah', 3, 19, 'ایصر د یشوع زوی چې د مصفې حاکم ؤ، د دېوال هغه بله برخه جوړه کړه چې هغې لارې ته مخامخ وه چې جبه خانې او د وسلو ګودام ته ورختلې وه او د دېوال تر کنجه پورې رسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_19.mp3', '', 1761754199, 1761754199),
(52853, 'Nehemiah 3:20', 'Nehemiah', 3, 20, 'باروک د زبای زوی د دېوال بله برخه چې د لوی کاهن الیاشیب د کور تر دروازې پورې رسېدله، جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_20.mp3', '', 1761754199, 1761754199),
(52854, 'Nehemiah 3:21', 'Nehemiah', 3, 21, 'مریموت چې د یوریا زوی او د هقوس لمسی ؤ، یوه بله برخه د الیاشیب د کور د دروازې څخه د هغه د کور تر پایه پورې جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_21.mp3', '', 1761754199, 1761754199),
(52855, 'Nehemiah 3:22', 'Nehemiah', 3, 22, 'هغه کاهنان چې د دېوال څو نورې برخې یې جوړې کړې، دا دي: د اورشلیم د شاوخوا سیمې کاهنانو د دېوال بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_22.mp3', '', 1761754199, 1761754199),
(52856, 'Nehemiah 3:23', 'Nehemiah', 3, 23, 'بنیامین او حشوب هغه برخه جوړه کړه چې د هغوی کور ته مخامخ وه. د معسیا زوی او د عننیا لمسي عزریا هغه برخه جوړه کړه چې د هغه د کور په خوا کې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_23.mp3', '', 1761754199, 1761754199),
(52857, 'Nehemiah 3:24', 'Nehemiah', 3, 24, 'بنوي د حیناداد زوی بله برخه جوړه کړه چې د عزریا د کور څخه د دېوال تر کنجه پورې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_24.mp3', '', 1761754199, 1761754199),
(52858, 'Nehemiah 3:27', 'Nehemiah', 3, 27, 'د تقوع خلکو د دېوال بله برخه جوړه کړه او دا د هغوی دوهمه برخه وه. هغه برخه د هغه ځای څخه پیل شوې وه چې د خدای د کور د څارنې لوی برج ته مخامخ وه او د عوفل تر دېواله پورې رسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_27.mp3', '', 1761754199, 1761754199),
(52859, 'Nehemiah 3:28', 'Nehemiah', 3, 28, 'د کاهنانو یوې ډلې د دېوال بله برخه جوړه کړه چې د اسونو د دروازې په شمال کې وه. هر یو په هغې برخې باندې کار کاوه چې د هغه د کور په مخکې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_28.mp3', '', 1761754199, 1761754199),
(52860, 'Nehemiah 3:29', 'Nehemiah', 3, 29, 'صادوق د یمیر زوی د دېوال بله برخه جوړه کړه چې د هغه د کور په مخکې وه. شمعیه د شکنیا زوی چې د ختیځې دروازې ساتونکی ؤ، د دېوال بله برخه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_29.mp3', '', 1761754199, 1761754199),
(52861, 'Nehemiah 3:30', 'Nehemiah', 3, 30, 'حننیا د شلمیا زوی او حانون د صالاف شپږم زوی د دېوال بله برخه جوړه کړه چې دا د هغوی دپاره دوهمه برخه وه. مشلام د برکیا زوی د دېوال بله برخه جوړه کړه چې د هغه د کور په مخکې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_30.mp3', '', 1761754199, 1761754199),
(52862, 'Nehemiah 3:31', 'Nehemiah', 3, 31, 'ملکیا چې یو زرګر ؤ، د دېوال هغه برخه جوړه کړه چې د خدای د کور د کارګرانو او سوداګرانو تر کوره پورې رسېدله. دا ځای د حاضرۍ دروازې ته مخامخ ؤ چې هغې کوټې ته نژدې ؤ چې د دېوال په شمال ختیځ کنج باندې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_31.mp3', '', 1761754199, 1761754199),
(52863, 'Nehemiah 3:32', 'Nehemiah', 3, 32, 'زرګرانو او سوداګرانو د دېوال وروستنۍ برخه چې د کنج د کوټې څخه د پسونو تر دروازې پورې رسېدله، جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah3_verse_32.mp3', '', 1761754199, 1761754199),
(52864, 'Genesis 37:1', 'Genesis', 37, 1, 'یعقوب په کنعان کې په هغه ځای کې ژوند کاوه چېرته چې د هغه پلار اوسېدلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_1.mp3', '', 1761754199, 1761754199),
(52865, 'Genesis 37:2', 'Genesis', 37, 2, 'دا د یعقوب د کورنۍ کیسه ده. یوسف اوولس کلن ځوان ؤ او د خپلو ناسکه ورونو سره یې چې د بلهې او زلفې زامن وو رمې ساتلې. یوسف به خپل پلار د خپلو ورونو د بدو کارونو څخه خبراوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_2.mp3', '', 1761754199, 1761754199),
(52866, 'Genesis 37:3', 'Genesis', 37, 3, 'یعقوب د یوسف سره د خپلو نورو ټولو زامنو څخه زیاته مینه کوله، ځکه چې هغه ورته په زوړوالي کې پیدا شوی ؤ. د هغه دپاره یې ښکلې چپنه جوړه کړه چې اوږده لستوڼي یې درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_3.mp3', '', 1761754199, 1761754199),
(52867, 'Genesis 37:4', 'Genesis', 37, 4, 'کله چې د هغه ورونه په دې پوه شول چې د هغوی پلار د یوسف سره د هغوی څخه زیاته مینه کوي، نو د یوسف څخه یې ډېره کرکه کوله او په نرمه ژبه یې ورسره خبرې نه کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_4.mp3', '', 1761754199, 1761754199),
(52868, 'Genesis 37:5', 'Genesis', 37, 5, 'یوه شپه یوسف خوب ولیده او هغه یې خپلو ورونو ته بیان کړ، نو د یوسف سره د هغوی کینه نوره هم زیاته شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_5.mp3', '', 1761754199, 1761754199),
(52869, 'Genesis 37:6', 'Genesis', 37, 6, 'هغوی ته یې وویل: «ما چې کوم خوب لیدلی دی هغه ته غوږ ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_6.mp3', '', 1761754199, 1761754199),
(52870, 'Genesis 37:7', 'Genesis', 37, 7, 'مونږ په پټي کې د غلو دانو ګېډۍ تړلې او ناڅاپه زما ګېډۍ پورته شوه او نېغه ودرېدله او ستاسو ګېډۍ زما د ګېډۍ په شاوخوا باندې راټولې شوې او زما ګېډۍ ته یې د درناوي په خاطر سرونه ټیټ کړل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_7.mp3', '', 1761754199, 1761754199),
(52871, 'Genesis 37:8', 'Genesis', 37, 8, 'د هغه ورونو پوښتنه وکړه: «ایا ته غواړې چې پاچا شې او په مونږ باندې حکومت وکړې؟» نو د یوسف د خوبونو په سبب او د هغو شیانو له امله چې د هغوی په اړه یې وویل د هغه د ورونو کینه نوره هم زیاته شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_8.mp3', '', 1761754199, 1761754199),
(52872, 'Genesis 37:9', 'Genesis', 37, 9, 'بیا یوسف بل خوب ولیده او خپلو ورونو ته یې بیان کړ: «ما بل خوب ولیده چې په هغه کې لمر، سپوږمۍ او یوولس ستورو د درناوي په خاطر ماته خپل سرونه ټیټ کړل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_9.mp3', '', 1761754199, 1761754199),
(52873, 'Genesis 37:10', 'Genesis', 37, 10, 'هغه دا خوب خپل پلار ته هم بیان کړ. د هغه پلار هغه ورټلو او ویې ویل: «دا څه ډول خوب دی چې تا لیدلی دی؟ ایا په رښتیا سره به زه، ستا مور او ستا ورونه تاته راځو او تاته به د درناوي سرونه ټیټوو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_10.mp3', '', 1761754199, 1761754199),
(52874, 'Genesis 37:11', 'Genesis', 37, 11, 'د یوسف ورونو د هغه سره کینه درلودله، خو د هغه پلار دا موضوع په خپل ذهن کې وساتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_11.mp3', '', 1761754199, 1761754199),
(52875, 'Genesis 37:12', 'Genesis', 37, 12, 'یوه ورځ د یوسف ورونه د رمو د څرولو دپاره شکیم ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_12.mp3', '', 1761754199, 1761754199),
(52876, 'Genesis 37:13', 'Genesis', 37, 13, 'یعقوب یوسف ته وویل: «ستا ورونه شکیم ته نژدې رمې څروي. زه غواړم چې تا هغوی ته ورولېږم.» هغه ځواب ورکړ: «ډېره ښه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_13.mp3', '', 1761754199, 1761754199),
(52877, 'Genesis 37:14', 'Genesis', 37, 14, 'د هغه پلار وویل: «لاړ شه او وګوره چې ستا ورونه روغ رمټ دي او رمې روغې جوړې دي که نه، ماته بېرته خبر راوړه.» نو هغه یې د حبرون له درې څخه ولېږه. یوسف شکیم ته ورسېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_14.mp3', '', 1761754199, 1761754199),
(52878, 'Genesis 37:15', 'Genesis', 37, 15, 'او په صحرا کې شاوخوا سرګردانه ګرځېده. یو سړي هغه ولیده او پوښتنه یې ترې وکړه: «څه شی لټوې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_15.mp3', '', 1761754199, 1761754199),
(52879, 'Genesis 37:16', 'Genesis', 37, 16, 'هغه ځواب ورکړ: «زه خپل ورونه لټوم. ایا ماته ویلی شې چې هغوی چېرته خپلې رمې څروي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_16.mp3', '', 1761754199, 1761754199),
(52880, 'Genesis 37:17', 'Genesis', 37, 17, 'هغه سړي ځواب ورکړ: «هغوی پخوا له دې ځای نه تللي دي. د هغوی څخه مې واورېدل چې ویل یې، راځئ چې دوتان ته لاړ شو.» نو یوسف خپلو ورونو پسې لاړ او په دوتان کې یې هغوی پیدا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_17.mp3', '', 1761754199, 1761754199),
(52881, 'Genesis 37:18', 'Genesis', 37, 18, 'هغوی یوسف د لېرې نه ولیده او مخکې له دې چې یوسف دوی ته ورورسیږي، هغوی ورته دسیسه جوړه کړه چې ویې وژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_18.mp3', '', 1761754199, 1761754199),
(52882, 'Genesis 37:19', 'Genesis', 37, 19, 'هغوی یو بل ته سره وویل: «هغه دی، خوب لیدونکی راروان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_19.mp3', '', 1761754199, 1761754199),
(52883, 'Genesis 37:20', 'Genesis', 37, 20, 'راځئ چې هغه ووژنو او په یوې وچې څاه کې یې وغورځوو او وبه وایو چې هغه یو داړونکي ځناور وخوړ. بیا به وګورو چې د هغه خوبونه څنګه کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_20.mp3', '', 1761754199, 1761754199),
(52884, 'Genesis 37:21', 'Genesis', 37, 21, 'کله چې روبین دا خبره واورېدله، هڅه یې وکړه چې هغه د خپلو ورونو د لاسونو څخه خلاص کړي، نو هغه وویل: «هغه به نه وژنو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_21.mp3', '', 1761754199, 1761754199),
(52885, 'Genesis 37:22', 'Genesis', 37, 22, 'روبین هغوی ته وویل: «وینه مه تویوئ. هغه په دې څاه کې چې دلته په دې دښته کې ده وغورځوئ، خو لاس ورته مه اچوئ.» هغه دا خبره د دې دپاره وکړه چې یوسف د دوی څخه خلاص کړي او بېرته یې خپل پلار ته بوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_22.mp3', '', 1761754199, 1761754199),
(52886, 'Genesis 37:23', 'Genesis', 37, 23, 'نو کله چې یوسف خپلو ورونو ته راغی، هغوی ورڅخه هغه ښکلې چپنه چې اوږده لستوڼي یې درلودل، وویستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_23.mp3', '', 1761754199, 1761754199),
(52887, 'Genesis 37:24', 'Genesis', 37, 24, 'هغه یې ونیوه او په څاه کې یې وغورځاوه. څاه وچه وه او اوبه په کې نه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_24.mp3', '', 1761754199, 1761754199),
(52888, 'Genesis 37:25', 'Genesis', 37, 25, 'په هغه وخت کې چې دوی ډوډۍ خوړله، ناڅاپه یې ولیدل چې د اسماعیلیانو کاروان د جلعاد څخه راروان دی او د هغوی اوښان په مسالو، ملهمو او د مر کنډ باندې بار وو چې هغه مصر ته یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_25.mp3', '', 1761754199, 1761754199),
(52889, 'Genesis 37:26', 'Genesis', 37, 26, 'یهودا خپلو ورونو ته وویل: «د خپل ورور د وژلو او د هغه د قتل د پټولو څخه به مونږ ته څه ګټه راورسیږي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_26.mp3', '', 1761754199, 1761754199),
(52890, 'Genesis 37:27', 'Genesis', 37, 27, 'راځئ چې هغه په اسماعیلیانو باندې خرڅ کړو. مونږ به هغه ته زیان نه رسوو، ځکه چې هغه زمونږ ورور او زمونږ خپله وینه او خپل هډوکی دی.» د هغه ورونه په دې رضا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_27.mp3', '', 1761754199, 1761754199),
(52891, 'Genesis 37:28', 'Genesis', 37, 28, 'نو کله چې سوداګران تېرېدل، د هغه ورونو یوسف له څاه څخه راوویست او هغه یې په اسماعیلیانو باندې سپینو زرو په شلو سکو خرڅ کړ. هغوی یوسف مصر ته یووړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_28.mp3', '', 1761754199, 1761754199),
(52892, 'Genesis 37:29', 'Genesis', 37, 29, 'کله چې روبین بېرته څاه ته راغی او ویې لیدل چې یوسف هلته نشته، نو له غمه یې خپل کالي وشکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_29.mp3', '', 1761754199, 1761754199),
(52893, 'Genesis 37:30', 'Genesis', 37, 30, 'هغه بېرته خپلو ورونو ته ورغی او ویې ویل: «هلک هلته نشته، څه وکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_30.mp3', '', 1761754199, 1761754199),
(52894, 'Genesis 37:31', 'Genesis', 37, 31, 'بیا هغوی یو سېرلی حلال کړ او د یوسف چپنه یې د هغه په وینه کې غوټه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_31.mp3', '', 1761754199, 1761754199),
(52895, 'Genesis 37:32', 'Genesis', 37, 32, 'هغوی هغه چپنه بېرته خپل پلار ته یووړله او ویې ویل: «دا مونږ وموندله. وګوره چې دا ستا د زوی ده که نه؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_32.mp3', '', 1761754199, 1761754199),
(52896, 'Genesis 37:33', 'Genesis', 37, 33, 'یعقوب هغه وپېژندله او ویې ویل: «دا زما د زوی چپنه ده! کوم داړونکي ځناور هغه خوړلی دی او په رښتیا سره یوسف ټوټې ټوټې شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_33.mp3', '', 1761754199, 1761754199),
(52897, 'Genesis 37:34', 'Genesis', 37, 34, 'نو یعقوب له خفګانه خپل کالي وشکول. د ویر کالي یې واغوستل او ډېرې ورځې د خپل زوی دپاره غمجن ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_34.mp3', '', 1761754199, 1761754199),
(52898, 'Genesis 37:35', 'Genesis', 37, 35, 'د هغه ټول زامن او لورګانې راغلې چې هغه ته تسلي ورکړي، خو هغه دا تسلي ونه منله او ویې ویل: «د خپل زوی دپاره به زه د دې غم سره قبر ته ځم.» نو پلار یې د هغه دپاره وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_35.mp3', '', 1761754199, 1761754199),
(52899, 'Genesis 37:36', 'Genesis', 37, 36, 'په هغه وخت کې سوداګرانو یوسف په مصر کې په فوطیفار باندې چې د فرعون د درباریانو څخه ؤ او د دربار د ساتونکو قوماندان ؤ، خرڅ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis37_verse_36.mp3', '', 1761754199, 1761754199),
(52900, 'Micah 1:1', 'Micah', 1, 1, 'په هغه وخت کې چې یوتام، آحاز او حزقیا د یهودا پاچاهان وو، څښتن دا پیغام میکاه ته چې د مورشیت د ښارګوټي څخه ؤ، ورکړ. میکاه د سامرې او اورشلیم په هکله دا رویا ولیدله:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_1.mp3', '', 1761754199, 1761754199),
(52901, 'Micah 1:2', 'Micah', 1, 2, 'ای ټولو قومونو، واورئ دا خبره ای د ځمکې په مخ ټولو اوسېدونکو خلکو غوږ ونیسئ څښتن تعالی ورکوي شاهدي ستاسو خلاف هغه خبرې کوي له خپل سپېڅلي معبده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_2.mp3', '', 1761754199, 1761754199),
(52902, 'Micah 1:3', 'Micah', 1, 3, 'ګورئ څښتن راځي له خپله ځایه هغه لاندې راځي او ګرځي د غرونو په سرونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_3.mp3', '', 1761754199, 1761754199),
(52903, 'Micah 1:4', 'Micah', 1, 4, 'داسې ویلي کیږي غرونه د هغه د پښو لاندې لکه موم چې ویلي کیږي اور کې داسې راتوییږي درو ته لکه اوبه چې راتوییږي له غونډیو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_4.mp3', '', 1761754199, 1761754199),
(52904, 'Micah 1:5', 'Micah', 1, 5, 'دا هرڅه به پېښ شي، ځکه چې د اسراییلو قوم سرکښي او ګناه کړې ده. د اسراییلو د سرکښۍ په خاطر څوک ملامته دی؟ سامره یعنې په خپله پایتخت! په یهودا کې د بت‌پرستۍ مرکز چېرته دی؟ په خپله اورشلیم!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_5.mp3', '', 1761754199, 1761754199),
(52905, 'Micah 1:6', 'Micah', 1, 6, 'څښتن وایي: «نو زه به سامره په کنډوالو یعنې داسې ځای باندې بدله کړم چې د انګورو تاکونه په کې کرل کیږي. زه به د ښار د خاورو او خښتو ډېرۍ لاندې درې ته وغورځوم او د ښار بنیادونه به لوڅ پراته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_6.mp3', '', 1761754199, 1761754199),
(52906, 'Micah 1:7', 'Micah', 1, 7, 'د هغې ټول قیمتي بتان به ټوټې ټوټې شي او د هغې د بدلمنتوب ټوله ګټه به په اور کې وسوځول شي او ټولې مجسمې به یې ویجاړې شي. اوس به یې دښمنان هغه شیان نورو ځایونو ته د فاحشو د اجورې دپاره یوسي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_7.mp3', '', 1761754199, 1761754199),
(52907, 'Micah 1:8', 'Micah', 1, 8, 'نو میکاه وویل: «په دې سبب به زه ژړا او ویر کوم. د خپل غم د ښکاره کولو په خاطر به زه لوڅې پښې او لوڅ بدن ګرځم. زه به د سورلنډي په شان انګولم او د شترمرغ په شان به ژړا او انګولا کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_8.mp3', '', 1761754199, 1761754199),
(52908, 'Micah 1:9', 'Micah', 1, 9, 'ځکه چې د سامرې ناروغي نه رغیږي او تر یهودا پورې خپره شوې ده. حتی هغه ناروغي د اورشلیم تر دروازو پورې یعنې چېرته چې زما قوم اوسیږي، هم رارسېدلې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_9.mp3', '', 1761754199, 1761754199),
(52909, 'Micah 1:10', 'Micah', 1, 10, 'نو میکاه د یهودا خلکو ته وویل:« په جت کې زمونږ دښمنان زمونږ د ماتې نه مه خبروئ او مه پرېږدئ چې هغوی ستاسو ژړا وویني. ای د بیت‌عفره خلکو، په خاورو کې ورغړېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_10.mp3', '', 1761754199, 1761754199),
(52910, 'Micah 1:11', 'Micah', 1, 11, 'ای د شافیر د ښار خلکو، زمونږ دښمنان به تاسو لوڅ کړي او تاسو به په شرم سره مجبور کړي چې جلاوطنه شئ. د صعنان د ښار خلک نه شي کولای چې د ښار نه ووځي. کله چې تاسو د بیت‌ایزل د ښار د خلکو ویرونه واورئ، نو تاسو به پوه شئ چې هلته هم د پناه ځای نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah1_verse_11.mp3', '', 1761754199, 1761754199);